use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &mut Vec<i32>)
    requires
        old(a).len() > 0,
    ensures
        // length is unchanged
        a.len() == old(a).len(),

        // first/last are swapped
        a[0] == old(a)[old(a).len() - 1],
        a[a.len() - 1] == old(a)[0],

        // all middle elements unchanged
        forall|i: int|
            0 < i && i < a.len() - 1 ==> a[i] == old(a)[i],
{
    let n = a.len();
    // Needed so we can safely read a[n-1] and a[0]
    assert(n > 0);

    if n == 1 {
        // Swapping the only element is a no-op; all postconditions follow trivially.
        return;
    }

    let first = a[0];
    let last = a[n - 1];

    a.set(0, last);
    a.set(n - 1, first);

    // Middle elements were never modified; establish the quantified postcondition.
    assert(forall|i: int|
        0 < i && i < a.len() - 1 ==> a[i] == old(a)[i]
    );
}

} // verus!

